    if(structure==='exchange')return `<section class="exp-custom exp-xp exp-xp-exchange">${top}<div class="exp-exchange-grid"><section><small>SOURCE</small><h2>${meta.input}</h2>${fields}${privacy}</section><div class="exp-exchange-core"><i data-lucide="arrow-left-right"></i>${run}<span>LOCAL</span>${reset}</div><section><small>TARGET</small><h2>${meta.output}</h2>${signature}${result}</section></div></section>`;
    if(structure==='timeline')return `<section class="exp-custom exp-xp exp-xp-timeline">${top}<div class="exp-time-ruler">${Array.from({length:12},(_,index)=>`<i><span>${String(index*5).padStart(2,'0')}:00</span></i>`).join('')}</div><div class="exp-time-track"><span></span><b></b><em></em><i></i></div><div class="exp-time-work"><section><h2>${meta.input}</h2>${fields}${actions}${privacy}</section><section><div class="exp-xp-heading"><h2>${meta.output}</h2>${tools}</div>${signature}${result}</section></div></section>`.replace(/<div class="row exp-output-tools">[\s\S]*?<\/div><\/header>/,'</header>');
    if(structure==='document')return `<article class="exp-custom exp-xp exp-xp-document">${top}<div class="exp-document-bar"><span></span><span></span><span></span><b>${slug.replaceAll('-',' ')}</b></div><div class="exp-document-sheet"><aside>01<br>02<br>03<br>04<br>05<br>06</aside><section><h2>${meta.input}</h2>${fields}${actions}${privacy}</section><section><h2>${meta.output}</h2>${signature}${result}</section></div></article>`;
    if(structure==='ide')return `<section class="exp-custom exp-xp exp-xp-ide"><header><i></i><i></i><i></i><b>${slug}.tool</b>${tools}</header><div class="exp-ide-body"><nav><span>EXPLORER</span><i data-lucide="files"></i><i data-lucide="search"></i><i data-lucide="git-branch"></i><i data-lucide="settings"></i></nav><aside><small>CONFIG</small><h2>${meta.input}</h2>${fields}${actions}${privacy}</aside><main><div class="exp-ide-tabs"><span>OUTPUT</span><span>PREVIEW</span></div>${signature}${result}</main></div></section>`;
